// The demo's link-preview and tab icons: generated by scripts/demo-assets.py from brand/logo.svg, the demo fonts and
// the og.* text in i18n, then committed. These tests pin the shape of what is committed (sizes, formats, one card per
// language), not the words or the pixels, so the text can change in i18n and the card be regenerated freely.
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

const assets = new URL('../assets/', import.meta.url)
const read = (name) => readFileSync(new URL(name, assets))
const i18n = (lang) => JSON.parse(readFileSync(new URL(`../i18n/${lang}.json`, import.meta.url), 'utf8'))
const PNG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])
const pngSize = (b) => [b.readUInt32BE(16), b.readUInt32BE(20)]
// WhatsApp drops a preview image over about 300 KB.
const PREVIEW_LIMIT = 300 * 1024

describe('demo meta assets', () => {
  it('has one 1200x630 PNG link-preview card per language, each under the 300 KB preview limit', () => {
    const cards = ['og-ms.png', 'og-en.png'].map(read)
    for (const card of cards) {
      expect(card.subarray(0, 8).equals(PNG)).toBe(true)
      expect(pngSize(card)).toEqual([1200, 630])
      expect(card.length).toBeLessThanOrEqual(PREVIEW_LIMIT)
    }
    expect(cards[0].equals(cards[1])).toBe(false)
  })

  it('has a favicon.ico holding 16, 32 and 48 px PNG images', () => {
    const ico = read('favicon.ico')
    expect([...ico.subarray(0, 4)]).toEqual([0, 0, 1, 0])
    const count = ico.readUInt16LE(4)
    const sizes = []
    for (let i = 0; i < count; i++) {
      const entry = 6 + 16 * i
      const [w, h] = [ico[entry] || 256, ico[entry + 1] || 256]
      const length = ico.readUInt32LE(entry + 8)
      const offset = ico.readUInt32LE(entry + 12)
      const image = ico.subarray(offset, offset + length)
      expect(image.subarray(0, 8).equals(PNG)).toBe(true)
      expect(pngSize(image)).toEqual([w, h])
      sizes.push(w)
    }
    expect(sizes).toEqual([16, 32, 48])
  })

  it('has a 180x180 apple-touch-icon and a script-free SVG favicon', () => {
    const touch = read('apple-touch-icon.png')
    expect(touch.subarray(0, 8).equals(PNG)).toBe(true)
    expect(pngSize(touch)).toEqual([180, 180])
    const svg = read('favicon.svg').toString('utf8')
    expect(svg).toMatch(/^<svg [^>]*xmlns="http:\/\/www\.w3\.org\/2000\/svg"/)
    expect(svg).not.toMatch(/<script|\bon[a-z]+=|href=/i)
  })

  it('takes the card text and its alt text from i18n, with the same og keys in both languages', () => {
    const [ms, en] = [i18n('ms'), i18n('en')]
    expect(Object.keys(ms.og).sort()).toEqual(Object.keys(en.og).sort())
    for (const key of ['headline', 'kicker', 'alt']) {
      for (const og of [ms.og, en.og]) {
        expect(typeof og[key]).toBe('string')
        expect(og[key].trim().length).toBeGreaterThan(0)
      }
      expect(ms.og[key]).not.toBe(en.og[key])
    }
  })
})
